"""Input and output functions for FoodomicsPy.This module contains functions for reading LF-NMR and FTIR data,and for saving and loading pandas DataFrames in HDF5 format."""import refrom pathlib import Pathfrom typing import Unionimport numpy as npimport pandas as pdimport nmrglue as ng# =============================================================================# LF-NMR XML READER# =============================================================================def load_lf_nmr(path):    """    Load Oxford LF-NMR XML files from a folder and its subfolders.    The real and imaginary signal components are extracted from each    XML file and converted to signal magnitude.    Parameters    ----------    path : str or pathlib.Path        Folder containing LF-NMR XML files. Subfolders are searched        recursively.    Returns    -------    pandas.DataFrame        LF-NMR data with:        - samples in rows,        - time in milliseconds in columns,        - signal magnitude as values.    Raises    ------    FileNotFoundError        If the specified folder does not exist.    NotADirectoryError        If the specified path is not a folder.    ValueError        If no valid LF-NMR spectra are found.    Examples    --------    >>> import foodomicspy as f    >>> df = f.io.load_lf_nmr("data/lf_nmr")    >>> df.shape    (20, 2000)    """    path = Path(path)    if not path.exists():        raise FileNotFoundError(            f"Folder was not found: {path}"        )    if not path.is_dir():        raise NotADirectoryError(            f"Expected a folder, received: {path}"        )    files = sorted(        path.rglob("*.xml"),        key=lambda file: (            str(file.parent),            [                int(value) if value.isdigit() else value                for value in re.split(r"(\d+)", file.stem)            ],        ),    )    spectra = {}    time_axis = None    for file in files:        try:            text = file.read_text(errors="ignore")        except Exception:            continue        if "Seconds" not in text:            continue        lines = text.splitlines()        seconds = []        real = []        imag = []        current = None        for line in lines:            line = line.strip()            if 'Column Name="Seconds"' in line:                current = seconds                continue            if 'Column Name="Real"' in line:                current = real                continue            if 'Column Name="Imaginary"' in line:                current = imag                continue            match = re.search(                r"<Value>(.*?)</Value>",                line,            )            if match and current is not None:                current.append(float(match.group(1)))        if not (            len(seconds)            == len(real)            == len(imag)        ):            continue        magnitude = np.sqrt(            np.square(real) + np.square(imag)        )        spectra[file.stem] = magnitude        time_axis = np.asarray(seconds) * 1000    if not spectra or time_axis is None:        raise ValueError(            f"No valid LF-NMR XML spectra were found in: {path}"        )    df = pd.DataFrame(spectra).T    df.columns = time_axis    df.columns.name = "time_ms"    df.index.name = "sample_id"    return df# =============================================================================# HDF5 WRITING# =============================================================================def save_hdf(df, path, key="data"):    """    Save a DataFrame as a compressed HDF5 file.    The output folder is created automatically when it does not    already exist.    Parameters    ----------    df : pandas.DataFrame        DataFrame to save.    path : str or pathlib.Path        Output HDF5 file path.    key : str, default="data"        Name used to store the DataFrame inside the HDF5 file.    Returns    -------    pathlib.Path        Path to the saved HDF5 file.    Examples    --------    Save a DataFrame using the default key:    >>> import foodomicspy as f    >>> saved_path = f.io.save_hdf(    ...     df,    ...     "data/spectra.h5",    ... )    Save a DataFrame using a custom key:    >>> saved_path = f.io.save_hdf(    ...     df,    ...     "data/spectra.h5",    ...     key="spectra",    ... )    """    path = Path(path)    path.parent.mkdir(        parents=True,        exist_ok=True,    )    df.to_hdf(        path,        key=key,        mode="w",        format="fixed",        complevel=9,        complib="zlib",    )    return path# =============================================================================# HDF5 READING# =============================================================================def read_hdf(path, key="data"):    """    Read a DataFrame from an HDF5 file.    Parameters    ----------    path : str or pathlib.Path        Path to the HDF5 file.    key : str, default="data"        Name of the DataFrame stored inside the HDF5 file.    Returns    -------    pandas.DataFrame        DataFrame loaded from the HDF5 file.    Raises    ------    FileNotFoundError        If the specified HDF5 file does not exist.    Examples    --------    Read data stored under the default key:    >>> import foodomicspy as f    >>> df = f.io.read_hdf("data/spectra.h5")    Read data stored under a custom key:    >>> df = f.io.read_hdf(    ...     "data/spectra.h5",    ...     key="spectra",    ... )    """    path = Path(path)    if not path.exists():        raise FileNotFoundError(            f"HDF5 file was not found: {path}"        )    return pd.read_hdf(        path,        key=key,    )# =============================================================================# HDF5 KEY INSPECTION# =============================================================================def list_hdf_keys(path):    """    List all dataset keys stored in an HDF5 file.    Parameters    ----------    path : str or pathlib.Path        Path to the HDF5 file.    Returns    -------    list of str        Names of the datasets stored in the HDF5 file.    Raises    ------    FileNotFoundError        If the specified HDF5 file does not exist.    Examples    --------    >>> import foodomicspy as f    >>> keys = f.io.list_hdf_keys("data/spectra.h5")    >>> print(keys)    ['data']    """    path = Path(path)    if not path.exists():        raise FileNotFoundError(            f"HDF5 file was not found: {path}"        )    with pd.HDFStore(path, mode="r") as store:        return [            key.lstrip("/")            for key in store.keys()        ]# =============================================================================# BRUKER OPUS READER# =============================================================================def read_opus(    folder_path: Union[str, Path],    strict_axis: bool = True,    verbose: bool = True,) -> pd.DataFrame:    """    Read absorbance spectra from Bruker OPUS ``.0`` files.    Each file is read from the OPUS absorbance block ``AB``. Spectra    are returned with samples in rows and wavenumbers in columns.    Parameters    ----------    folder_path : str or pathlib.Path        Folder containing Bruker OPUS ``.0`` files.    strict_axis : bool, default=True        Determine how spectra with different wavenumber axes are        handled.        If `True`, files with an axis different from the first        successfully loaded spectrum are skipped.        If `False`, spectra with different axes are interpolated onto        the axis of the first successfully loaded spectrum.    verbose : bool, default=True        Print information about loaded, skipped, interpolated, or        unreadable files.    Returns    -------    pandas.DataFrame        Spectral matrix with samples in rows and wavenumbers in columns.        Sample names are obtained from file names without extensions.    Raises    ------    FileNotFoundError        If `folder_path` does not exist.    NotADirectoryError        If `folder_path` is not a folder.    ImportError        If `brukeropusreader` is not installed.    Notes    -----    Only the OPUS absorbance block ``AB`` is read.    When `strict_axis=False`, interpolation is performed only within    the wavenumber range of the source spectrum. Values outside the    source range are returned as ``NaN``.    Examples    --------    Read spectra and require identical wavenumber axes:    >>> import foodomicspy as f    >>> df = f.io.read_opus(    ...     "data/ftir",    ...     strict_axis=True,    ... )    Interpolate spectra with different axes:    >>> df = f.io.read_opus(    ...     "data/ftir",    ...     strict_axis=False,    ...     verbose=False,    ... )    """    try:        from brukeropusreader import read_file    except ImportError as exc:        raise ImportError(            "Reading OPUS files requires 'brukeropusreader'. "            "Install it with: pip install brukeropusreader"        ) from exc    folder = Path(folder_path).expanduser()    if not folder.exists():        raise FileNotFoundError(            f"Folder not found: {folder}"        )    if not folder.is_dir():        raise NotADirectoryError(            f"Expected a folder, received: {folder}"        )    files = sorted(        path        for path in folder.iterdir()        if path.is_file()        and path.suffix.lower() == ".0"    )    if not files:        if verbose:            print(                f"No OPUS .0 files found in: {folder}"            )        return pd.DataFrame()    spectra: dict[str, np.ndarray] = {}    reference_axis: np.ndarray | None = None    for file_path in files:        try:            opus_data = read_file(                str(file_path)            )            if "AB" not in opus_data:                if verbose:                    print(                        f"Skipped {file_path.name}: "                        "no 'AB' block."                    )                continue            x = np.asarray(                opus_data.get_range("AB"),                dtype=float,            ).squeeze()            y = np.asarray(                opus_data["AB"],                dtype=float,            ).squeeze()            if x.ndim != 1 or y.ndim != 1:                raise ValueError(                    "The wavenumber axis and absorbance values "                    "must be one-dimensional."                )            if x.size != y.size:                raise ValueError(                    "Axis and spectrum lengths differ: "                    f"{x.size} wavenumbers and "                    f"{y.size} absorbance values."                )            if x.size < 2:                raise ValueError(                    "The spectrum contains fewer than two data points."                )            if not np.all(np.isfinite(x)):                raise ValueError(                    "The wavenumber axis contains non-finite values."                )            if reference_axis is None:                reference_axis = x.copy()            elif not np.allclose(                reference_axis,                x,                rtol=1e-7,                atol=1e-8,            ):                if strict_axis:                    if verbose:                        print(                            f"Skipped {file_path.name}: "                            "wavenumber axis differs from "                            "the reference axis."                        )                    continue                y = _interpolate_spectrum(                    source_axis=x,                    source_values=y,                    target_axis=reference_axis,                )                if verbose:                    print(                        f"Interpolated {file_path.name} "                        "onto the reference wavenumber axis."                    )            spectra[file_path.stem] = y            if verbose:                print(                    f"Loaded {file_path.name}"                )        except Exception as exc:            if verbose:                print(                    f"Could not read "                    f"{file_path.name}: {exc}"                )    if not spectra or reference_axis is None:        return pd.DataFrame()    result = pd.DataFrame.from_dict(        spectra,        orient="index",        columns=reference_axis,    )    result.index.name = "sample"    result.columns.name = "wavenumber_cm-1"    return result# =============================================================================# BENCHTOP NMR READER# =============================================================================def read_benchtop(    folder_path: Union[str, Path],    strict_axis: bool = False,    verbose: bool = True,) -> pd.DataFrame:    """    Read processed benchtop NMR spectra from CSV files.    The function recursively searches for files named    ``spectrum_processed.csv``. The first column is interpreted as the    chemical-shift axis and the second column as signal intensity.    Sample IDs are obtained directly from the parent folder names    without modification. Duplicate sample IDs are retained.    Parameters    ----------    folder_path : str or pathlib.Path        Parent folder containing processed benchtop NMR spectra.        Subfolders are searched recursively.    strict_axis : bool, default=False        Determine how spectra with different chemical-shift axes are        handled.        If `True`, spectra with an axis different from the first        successfully loaded spectrum are skipped.        If `False`, spectra with different axes are interpolated onto        the axis of the first successfully loaded spectrum.    verbose : bool, default=True        Print information about loaded, skipped, interpolated, or        unreadable files.    Returns    -------    pandas.DataFrame        Spectral matrix with samples in rows and chemical shifts in        columns.        Sample IDs are obtained directly from parent folder names.        Duplicate index values may therefore be present.    Raises    ------    FileNotFoundError        If `folder_path` does not exist.    NotADirectoryError        If `folder_path` is not a folder.    Notes    -----    The function attempts to read each file using the following CSV    formats:    - semicolon separator with decimal comma;    - comma separator with decimal point;    - tab separator with decimal point.    When `strict_axis=False`, interpolation is performed only within    the chemical-shift range of the source spectrum. Values outside    that range are returned as ``NaN``.    Examples    --------    Read spectra and automatically interpolate differing axes:    >>> import foodomicspy as f    >>> df = f.io.read_benchtop(    ...     "data/benchtop_nmr",    ... )    Require identical chemical-shift axes:    >>> df = f.io.read_benchtop(    ...     "data/benchtop_nmr",    ...     strict_axis=True,    ... )    """    folder = Path(folder_path).expanduser()    if not folder.exists():        raise FileNotFoundError(            f"Folder not found: {folder}"        )    if not folder.is_dir():        raise NotADirectoryError(            f"Expected a folder, received: {folder}"        )    files = sorted(        folder.rglob("spectrum_processed.csv"),        key=lambda file: str(file),    )    if not files:        if verbose:            print(                "No spectrum_processed.csv files found in: "                f"{folder}"            )        return pd.DataFrame()    spectra = []    sample_names = []    reference_axis = None    csv_formats = [        {"sep": ";", "decimal": ","},        {"sep": ",", "decimal": "."},        {"sep": "\t", "decimal": "."},    ]    for file_path in files:        # Keep the folder name exactly as it appears.        sample_name = file_path.parent.name        try:            spectrum_data = None            # Try the supported CSV formats.            for csv_format in csv_formats:                try:                    candidate = pd.read_csv(                        file_path,                        sep=csv_format["sep"],                        decimal=csv_format["decimal"],                    )                    if candidate.shape[1] >= 2:                        spectrum_data = candidate                        break                except Exception:                    continue            if spectrum_data is None:                raise ValueError(                    "The CSV file could not be read using the "                    "supported separator and decimal formats."                )            x = pd.to_numeric(                spectrum_data.iloc[:, 0],                errors="coerce",            ).to_numpy(dtype=float)            y = pd.to_numeric(                spectrum_data.iloc[:, 1],                errors="coerce",            ).to_numpy(dtype=float)            # Remove rows containing invalid axis or signal values.            valid = np.isfinite(x) & np.isfinite(y)            x = x[valid]            y = y[valid]            if x.ndim != 1 or y.ndim != 1:                raise ValueError(                    "The chemical-shift axis and signal values "                    "must be one-dimensional."                )            if x.size != y.size:                raise ValueError(                    "Axis and spectrum lengths differ: "                    f"{x.size} chemical-shift values and "                    f"{y.size} signal values."                )            if x.size < 2:                raise ValueError(                    "The spectrum contains fewer than two valid "                    "data points."                )            if reference_axis is None:                reference_axis = x.copy()            else:                same_axis = (                    reference_axis.shape == x.shape                    and np.allclose(                        reference_axis,                        x,                        rtol=1e-7,                        atol=1e-8,                    )                )                if not same_axis:                    if strict_axis:                        if verbose:                            print(                                f"Skipped {sample_name}: "                                "chemical-shift axis differs from "                                "the reference axis."                            )                        continue                    y = _interpolate_spectrum(                        source_axis=x,                        source_values=y,                        target_axis=reference_axis,                    )                    if verbose:                        print(                            f"Interpolated {sample_name} onto "                            "the reference chemical-shift axis."                        )            # Lists preserve duplicate sample names.            spectra.append(y)            sample_names.append(sample_name)            if verbose:                print(                    f"Loaded {sample_name}"                )        except Exception as exc:            if verbose:                print(                    f"Could not read {file_path}: {exc}"                )    if not spectra or reference_axis is None:        return pd.DataFrame()    result = pd.DataFrame(        data=np.vstack(spectra),        index=sample_names,        columns=reference_axis,    )    result.index.name = "sample"    result.columns.name = "chemical_shift_ppm"    return result# =============================================================================# READ BRUKER# =============================================================================def read_bruker(    folder_path,    verbose=True,    *,    id_from="dataset",    fill_outside=None,):    """    Read processed Bruker 1D NMR spectra.    The function recursively searches for processed Bruker spectra stored    as ``pdata/1/1r`` files. All spectra are interpolated onto the ppm axis    of the first successfully loaded spectrum.    Parameters    ----------    folder_path : str or pathlib.Path        Path to the folder containing one or more Bruker datasets.    verbose : bool, default=True        If True, print information about files that could not be read.    id_from : {"dataset", "foldername"}, default="dataset"        Method used to generate sample identifiers.        ``"dataset"``            Use the path of the Bruker dataset relative to            ``folder_path``.        ``"foldername"``            Use the name of the dataset folder containing the            ``pdata`` directory.    fill_outside : float or None, default=None        Value assigned to points outside the interpolation range.        If None, missing points are filled with ``numpy.nan``.    Returns    -------    pandas.DataFrame        Spectral data with samples in rows and ppm values in columns.        The ppm axis is arranged in descending order.    Raises    ------    TypeError        If ``folder_path`` is not a string or pathlib.Path, or if        ``verbose`` is not a boolean.    ValueError        If ``id_from`` is not ``"dataset"`` or ``"foldername"``.    FileNotFoundError        If ``folder_path`` does not exist.    RuntimeError        If no processed Bruker spectra are found or no valid spectra        can be loaded.    Notes    -----    The function searches specifically for processed spectra located at:    ``pdata/1/1r``    Since ``numpy.interp`` requires an increasing x-axis, each ppm axis    is temporarily converted to ascending order during interpolation    and then restored to descending order.    Examples    --------    Read all processed Bruker spectra from a folder:    >>> df = read_bruker("data/nmr")    Use only the dataset folder name as the sample identifier:    >>> df = read_bruker(    ...     "data/nmr",    ...     id_from="foldername",    ... )    Fill regions outside the available ppm range with zero:    >>> df = read_bruker(    ...     "data/nmr",    ...     fill_outside=0.0,    ... )    """    # -------------------------------------------------------------------------    # Validate inputs    # -------------------------------------------------------------------------    if not isinstance(folder_path, (str, Path)):        raise TypeError(            "`folder_path` must be a string or pathlib.Path."        )    if not isinstance(verbose, bool):        raise TypeError("`verbose` must be True or False.")    valid_id_options = {"dataset", "foldername"}    if id_from not in valid_id_options:        raise ValueError(            "`id_from` must be either 'dataset' or 'foldername'."        )    folder_path = Path(folder_path)    if not folder_path.exists():        raise FileNotFoundError(            f"Folder not found: {folder_path}"        )    if not folder_path.is_dir():        raise NotADirectoryError(            f"Path is not a folder: {folder_path}"        )    if fill_outside is None:        fill_outside = np.nan    # -------------------------------------------------------------------------    # Locate processed Bruker spectra    # -------------------------------------------------------------------------    files = sorted(folder_path.rglob("pdata/1/1r"))    if not files:        raise RuntimeError(            f"No processed Bruker spectra were found in: {folder_path}"        )    spectra = {}    reference_axis = None    # -------------------------------------------------------------------------    # Read spectra    # -------------------------------------------------------------------------    for file_path in files:        try:            # Determine sample identifier            dataset_folder = file_path.parents[2]            if id_from == "foldername":                sample_id = dataset_folder.name            else:                sample_id = str(                    dataset_folder.relative_to(folder_path)                )            # Read processed Bruker spectrum            dictionary, intensity = ng.bruker.read_pdata(                str(file_path.parent)            )            intensity = np.asarray(                intensity,                dtype=float,            ).squeeze()            if intensity.ndim != 1:                raise ValueError(                    "Only one-dimensional spectra are supported."                )            # Generate ppm axis            universal_dictionary = ng.bruker.guess_udic(                dictionary,                intensity,            )            unit_conversion = ng.fileiobase.uc_from_udic(                universal_dictionary            )            ppm_axis = np.asarray(                unit_conversion.ppm_scale(),                dtype=float,            )            if ppm_axis.size != intensity.size:                raise ValueError(                    "The ppm axis and intensity array have "                    "different lengths."                )            # Ensure descending ppm axis            if ppm_axis[0] < ppm_axis[-1]:                ppm_axis = ppm_axis[::-1]                intensity = intensity[::-1]            if not np.all(np.diff(ppm_axis) < 0):                raise ValueError(                    "The ppm axis is not strictly monotonic."                )            # Use the first valid spectrum as the reference            if reference_axis is None:                reference_axis = ppm_axis                spectra[sample_id] = intensity                if verbose:                    print(                        f"Loaded reference spectrum: {sample_id}"                    )                continue            # Interpolate onto the reference ppm axis            source_axis_ascending = ppm_axis[::-1]            source_values_ascending = intensity[::-1]            target_axis_ascending = reference_axis[::-1]            interpolated_values = np.interp(                target_axis_ascending,                source_axis_ascending,                source_values_ascending,                left=fill_outside,                right=fill_outside,            )            spectra[sample_id] = interpolated_values[::-1]        except Exception as error:            if verbose:                print(                    f"Skipped {file_path}: {error}"                )    # -------------------------------------------------------------------------    # Create output DataFrame    # -------------------------------------------------------------------------    if not spectra:        raise RuntimeError(            "No valid Bruker spectra could be loaded."        )    result = pd.DataFrame.from_dict(        spectra,        orient="index",        columns=reference_axis,    )    result.index.name = "sample"    result.columns.name = "ppm"    # Ensure descending ppm order    result = result.loc[        :,        sorted(result.columns, reverse=True),    ]    if verbose:        print(            f"Loaded {result.shape[0]} spectra with "            f"{result.shape[1]} spectral points."        )    return result# =============================================================================# INTERNAL HELPERS# =============================================================================def _interpolate_spectrum(    source_axis: np.ndarray,    source_values: np.ndarray,    target_axis: np.ndarray,) -> np.ndarray:    """    Interpolate a spectrum onto a target spectral axis.    This private helper supports both ascending and descending    source axes. Values outside the source-axis range are returned    as ``NaN``.    Parameters    ----------    source_axis : numpy.ndarray        Original spectral axis.    source_values : numpy.ndarray        Signal values associated with the original axis.    target_axis : numpy.ndarray        Spectral axis onto which the signal is interpolated.    Returns    -------    numpy.ndarray        Interpolated signal values.    """    order = np.argsort(source_axis)    source_axis_sorted = source_axis[order]    source_values_sorted = source_values[order]    unique_axis, unique_indices = np.unique(        source_axis_sorted,        return_index=True,    )    unique_values = source_values_sorted[        unique_indices    ]    interpolated = np.interp(        target_axis,        unique_axis,        unique_values,        left=np.nan,        right=np.nan,    )    return interpolated